export const MAX = 1024;

export function accept(body: string, declaredLength: number | null): boolean {
  if (declaredLength !== null && declaredLength > MAX) return false;
  return true;
}

import { expect, test } from "bun:test";
import { accept, MAX } from "./subject.js";

test("a declared oversize payload is refused", () => {
  expect(accept("x".repeat(MAX + 1), MAX + 1)).toBe(false);
});
test("an undeclared oversize payload is refused too", () => {
  expect(accept("x".repeat(MAX + 1), null)).toBe(false);
});
test("a payload within the cap is accepted either way", () => {
  expect(accept("x".repeat(10), 10)).toBe(true);
  expect(accept("x".repeat(10), null)).toBe(true);
});
test("a lying declaration does not get the payload in", () => {
  expect(accept("x".repeat(MAX + 1), 1)).toBe(false);
});
